dilutions":[{"scenario":"Maintenance / Light","ratio":"10:1"},{"scenario":"Standard","ratio":"10:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"4:1"}]},{"id":"a1000002-0000-0000-0000-000000000002","purpose":"General purpose cleaning for interior plastics and vinyl.","instructions":"Apply to cool surface. Follow dilution ratios based on dirt level. Agitate if necessary and rinse or wipe clean.","dilutions":[{"scenario":"Maintenance / Light","ratio":"10:1"},{"scenario":"Standard","ratio":"10:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"4:1"}]},{"id":"a1000003-0000-0000-0000-000000000003","purpose":"Premium carpet and upholstery cleaner. Deep cleans fibers without excessive foam.","instructions":"Spray onto carpet or fabric. Agitate with a stiff brush. Extract with wet/dry vac or wipe clean with microfiber.","dilutions":[{"scenario":"Maintenance / Light","ratio":"8:1"},{"scenario":"Standard","ratio":"7:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"5:1"}]},{"id":"a1000004-0000-0000-0000-000000000004","purpose":"Enzyme-based odor and stain remover. Direct application.","instructions":"Apply directly to stain or odor source. Allow enzymes to dwell 5-10 minutes. Blot or extract. Do not rinse for odor control.","dilutions":[{"scenario":"Maintenance / Light","ratio":"RTU"},{"scenario":"Standard","ratio":"RTU"},{"scenario":"Heavy Dirt / Degreasing","ratio":"RTU"}]},{"id":"a1000005-0000-0000-0000-000000000005","purpose":"Quick interior cleaner that leaves a perfect factory finish. Safe for all surfaces.","instructions":"Mist onto surface or applicator. Wipe to clean and buff to a satin finish. Safe for plastic, vinyl, leather, and rubber.","dilutions":[{"scenario":"Maintenance / Light","ratio":"3:1"},{"scenario":"Standard","ratio":"1:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"1:1"}]},{"id":"a1000006-0000-0000-0000-000000000006","purpose":"Rich foam car wash. Gently lifts dirt while conditioning paint.","instructions":"Mix with water in bucket or foam cannon. Wash top-down. Rinse thoroughly. Use grit guards to prevent swirl marks.","dilutions":[{"scenario":"Maintenance / Light","ratio":"5:1"},{"scenario":"Standard","ratio":"5:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"5:1"}]},{"id":"a1000007-0000-0000-0000-000000000007","purpose":"Powerful exterior pre-treat for bugs and road grime.","instructions":"Spray on cool surface. Allow 2-3 minute dwell time. Agitate with soft brush on heavy buildup. Rinse thoroughly.","dilutions":[{"scenario":"Maintenance / Light","ratio":"10:1"},{"scenario":"Standard","ratio":"10:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"4:1"}]},{"id":"a1000008-0000-0000-0000-000000000008","purpose":"Wheel and tire cleaner. Dissolves brake dust and road tar instantly.","instructions":"Spray on cool wheel. Allow 1-2 minutes to dwell (watch for color change on iron-reactive formulas). Agitate with wheel brush. Rinse well.","dilutions":[{"scenario":"Maintenance / Light","ratio":"10:1"},{"scenario":"Standard","ratio":"7:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"4:1"}]},{"id":"a1000009-0000-0000-0000-000000000009","purpose":"Rapid drying aid and polymer sealant. Fights hard water spots in direct sunlight.","instructions":"Spray onto wet paint after rinse. Spread with clean microfiber. Dry panel using blotting/pulling motion for spot-free finish.","dilutions":[{"scenario":"Maintenance / Light","ratio":"20:1"},{"scenario":"Standard","ratio":"20:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"20:1"}]},{"id":"a1000010-0000-0000-0000-000000000010","purpose":"Professional high-gloss paint protection. Apply to wet or dry surfaces.","instructions":"Mist onto clean panel. Spread evenly with applicator pad or microfiber. Buff off residue with clean microfiber towel.","dilutions":[{"scenario":"Maintenance / Light","ratio":"RTU"},{"scenario":"Standard","ratio":"RTU"},{"scenario":"Heavy Dirt / Degreasing","ratio":"RTU"}]},{"id":"a1000011-0000-0000-0000-000000000011","purpose":"Water-based tire and trim dressing. High shine without the sling.","instructions":"Apply to clean, dry tire or trim with applicator. Allow 2-3 minutes to bond. Buff off excess to prevent sling. Water-based ΓÇö will not sling.","dilutions":[{"scenario":"Maintenance / Light","ratio":"4:1"},{"scenario":"Standard","ratio":"2:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"1:1 (RTU)"}]},{"id":"a1000012-0000-0000-0000-000000000012","purpose":"Heavy-duty all-purpose cleaner for engines, wheel wells, and stubborn grease.","instructions":"Dilute per job type. Spray on surface. Agitate with brush. Rinse thoroughly. Avoid applying to hot surfaces or in direct sunlight.","dilutions":[{"scenario":"Maintenance / Light","ratio":"10:1"},{"scenario":"Standard","ratio":"4:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"4:1"}]},{"id":"a1000013-0000-0000-0000-000000000013","purpose":"Fast-acting wheel and tire cleaner for all wheel types.","instructions":"Spray directly onto wheel and tire. Allow 1-2 minutes to penetrate. Scrub with brush. Rinse with strong water stream.","dilutions":[{"scenario":"Maintenance / Light","ratio":"RTU"},{"scenario":"Standard","ratio":"RTU"},{"scenario":"Heavy Dirt / Degreasing","ratio":"RTU"}]}],"prepList":["a1000001-0000-0000-0000-000000000001","a1000002-0000-0000-0000-000000000002","a1000003-0000-0000-0000-000000000003","a1000004-0000-0000-0000-000000000004","a1000005-0000-0000-0000-000000000005","a1000006-0000-0000-0000-000000000006","a1000007-0000-0000-0000-000000000007","a1000008-0000-0000-0000-000000000008","a1000009-0000-0000-0000-000000000009","a1000010-0000-0000-0000-000000000010","a1000011-0000-0000-0000-000000000011","a1000012-0000-0000-0000-000000000012","a1000013-0000-0000-0000-000000000013"]}'::jsonb, updated_at = '2026-05-31T12:19:43.208Z'
